                      "type": "object",
                      "additionalProperties": {}
                    },
                    "maxItems": 100,
                    "description": "Records keyed by field key. Add \"$ref\": \"<short name>\" to a record so relation fields of other records in the plan can link to it; $ref is not stored."
                  }
