                  },
                  "page": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 200
                  },
                  "component": {
                    "type": "string",
                    "maxLength": 120
                  },
                  "file": {
                    "type": "string",
                    "maxLength": 300
                  },
                  "collection": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 120
                  },
                  "field": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 120
                  },
                  "target": {
                    "type": "string",
                    "enum": [
                      "text",
                      "rich_text",
                      "image",
                      "image_alt",
                      "link",
                      "number",
                      "date",
                      "boolean",
                      "collection",
                      "route_param",
                      "form_field",
                      "other"
                    ]
                  },
                  "required": {
                    "type": "boolean"
                  }
                },
                "required": [
                  "key",
                  "page",
                  "collection",
                  "target"
                ],
                "additionalProperties": false
              },
              "maxItems": 500
            },
            "notes": {
              "type": "array",
              "items": {
                "type": "string",
                "maxLength": 300
              },
              "maxItems": 20
            },
            "capabilities": {
              "type": "object",
              "properties": {
                "realtime": {
                  "type": "boolean"
                },
                "releaseRoute": {
                  "type": "string",
                  "minLength": 1,
