                                    "minLength": 1,
                                    "maxLength": 120
                                  },
                                  "type": {
                                    "type": "string",
                                    "enum": [
                                      "short_text",
                                      "long_text",
                                      "rich_text",
                                      "image",
                                      "number",
                                      "boolean",
                                      "date",
                                      "url",
                                      "email",
                                      "enum",
                                      "datetime",
                                      "file",
                                      "color",
                                      "json",
                                      "location"
                                    ]
                                  },
                                  "required": {
                                    "type": "boolean"
                                  },
                                  "helpText": {
                                    "type": "string",
                                    "maxLength": 500
                                  },
                                  "options": {
                                    "type": "array",
                                    "items": {
                                      "type": "string",
                                      "minLength": 1,
                                      "maxLength": 60
                                    },
                                    "minItems": 1,
                                    "maxItems": 50,
                                    "description": "For sub-field type enum only."
                                  },
                                  "sensitive": {
                                    "type": "boolean",
                                    "description": "Masked in lists and history and never delivered to the site — this sub-field's values stay with the editors."
                                  }
                                },
                                "required": [
                                  "displayName",
                                  "type"
                                ],
                                "additionalProperties": false
                              },
                              "minItems": 1,
                              "maxItems": 20
                            },
                            "repeatable": {
                              "type": "boolean",
                              "description": "true (default): a list of items; false: one nested object"
